  `califica_superiores` tinyint(1) DEFAULT '0',
  `califica_oficiales` tinyint(1) DEFAULT '0',
  `califica_suboficiales` tinyint(1) DEFAULT '0',
  `califica_encargados` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `concepto_id` (`concepto_id`),
  KEY `creado_por` (`creado_por`),
  CONSTRAINT `eventos_ibfk_1` FOREIGN KEY (`concepto_id`) REFERENCES `conceptos` (`id`),
  CONSTRAINT `eventos_ibfk_2` FOREIGN KEY (`creado_por`) REFERENCES `usuarios` (`id`)
